from __future__ import annotations
import math


def search_dimension(b: int, s: int) -> float:
    """Proof-search fractal dimension D(b, s) = log s / log b.

    Preconditions: b > 1 (genuine branching), 1 <= s <= b (solvable, self-similar).
    Returns a value in [0, 1].
    """
    if b <= 1:
        raise ValueError("branching factor b must satisfy b > 1")
    if not (1 <= s <= b):
        raise ValueError("success factor must satisfy 1 <= s <= b")
    return math.log(s) / math.log(b)

