function VERIFY_BRIDGE(b, s, n):
  D <- log(s)/log(b)
  succ <- s^n;  pred <- (b^n)^D
  return (succ, pred, |succ - pred|)

function DENSITY_CODIM(b, s, n):
  D <- log(s)/log(b)
  density <- (s/b)^n
  power   <- (b^n)^(D-1)
  return (density, power, 1 - D)

function SEARCH_COST(b, s, n):
  exhaustive <- (b^(n+1) - 1) / (b - 1)
  successful <- s^n
  return (exhaustive, successful, exhaustive/successful)
